import React, { useState, useEffect, useMemo } from "react";
import {
  View,
  Text,
  TouchableOpacity,
  ScrollView,
  Platform,
  useWindowDimensions,
  ActivityIndicator,
  Animated,
  Modal,
} from "react-native";
import { Colors } from "@/constants/colors";
import { getWebShadow, getWebCursor } from "@/constants/webStyles";
import { getSlotIndexFromStartTime } from "@/constants/scheduleSlots";
import { scheduleService } from "@/apis";
import { getStudentIdFromToken } from "@/apis/utils/jwt";
import type { Schedule } from "@/apis/services/schedule.service";
import { Ionicons } from "@expo/vector-icons";
import { useRouter } from "expo-router";

interface ScheduleItem {
  id: string;
  subject: string;
  code: string;
  sessions: string;
  room: string;
  teacher: string;
  type: "theory" | "practice" | "exam" | "makeup";
}

/** Cột giống lịch thật: Sáng (tiết 1-6), Chiều (7-12), Tối (13-15). Data map theo giờ vào đúng ca. */
interface DaySchedule {
  [dayName: string]: {
    morning?: ScheduleItem[];
    afternoon?: ScheduleItem[];
    evening?: ScheduleItem[];
  };
}

interface WeeklyScheduleProps {
  targetDate?: Date;
  teacherId?: string;
}

export default function WeeklySchedule({ targetDate, teacherId }: WeeklyScheduleProps = {}) {
  const router = useRouter();
  const [selectedView, setSelectedView] = useState<"all" | "class" | "exam">("all");
  const [currentWeek, setCurrentWeek] = useState(new Date());
  const [loading, setLoading] = useState(true);
  const [isChangingWeek, setIsChangingWeek] = useState(false);
  const [allSchedules, setAllSchedules] = useState<Schedule[]>([]);
  const [weeklySchedule, setWeeklySchedule] = useState<DaySchedule>({});
  const [modalItem, setModalItem] = useState<(ScheduleItem & { day: string }) | null>(null);
  const fadeAnim = React.useRef(new Animated.Value(1)).current;
  const { width: windowWidth } = useWindowDimensions();

  // Helper: get Monday of the week containing a given date
  const getWeekStart = (d: Date): Date => {
    const copy = new Date(d);
    const day = copy.getDay();
    const diff = copy.getDate() - day + (day === 0 ? -6 : 1);
    copy.setDate(diff);
    copy.setHours(0, 0, 0, 0);
    return copy;
  };

  // When parent selects a day from MonthCalendar, navigate to that week (skip if already in current week)
  useEffect(() => {
    if (!targetDate) return;
    const targetWeekStart = getWeekStart(targetDate);
    const currentWeekStart = getWeekStart(currentWeek);
    // Same week → no-op, avoids unnecessary refetch
    if (targetWeekStart.getTime() === currentWeekStart.getTime()) return;
    // Different week → fade + navigate
    setIsChangingWeek(true);
    Animated.timing(fadeAnim, {
      toValue: 0.3,
      duration: 150,
      useNativeDriver: true,
    }).start(() => {
      setCurrentWeek(new Date(targetDate));
    });
  }, [targetDate]);


  // Responsive breakpoints
  const isMobile = windowWidth < 768;
  const isTablet = windowWidth >= 768 && windowWidth < 1024;

  // Responsive values
  const columnMinWidth = isMobile ? 180 : 240;

  const headerPadding = isMobile ? 10 : 14;
  const headerFontSize = isMobile ? 13 : 15;
  const dayFontSize = isMobile ? 12 : 14;
  const periodFontSize = isMobile ? 12 : 14;

  // Data theo giờ (11:00, 13:30...) → map đúng ca Sáng/Chiều/Tối (tiết 1-6 sáng, 7-12 chiều, 13-15 tối)
  const convertSchedulesToDaySchedule = (
    schedules: Schedule[],
  ): DaySchedule => {
    const dayNames = [
      "sunday",
      "monday",
      "tuesday",
      "wednesday",
      "thursday",
      "friday",
      "saturday",
    ];
    const scheduleMap: DaySchedule = {};
    dayNames.forEach((d) => {
      scheduleMap[d] = { morning: [], afternoon: [], evening: [] };
    });

    schedules.forEach((s: Schedule) => {
      const dayIndex = s.dayOfWeek === 8 ? 0 : (s.dayOfWeek ?? 2) - 1;
      const dayName = dayNames[dayIndex] ?? "monday";
      const slotIndex = getSlotIndexFromStartTime(s.startTime ?? "");
      
      // Phân bổ ca dựa trên giờ thực tế (đảm bảo 16h30 là Chiều, và các giờ tối > 18h là Tối)
      let period: "morning" | "afternoon" | "evening" = "morning";
      const h = parseInt((s.startTime ?? "0").split(":")[0], 10);
      if (h >= 18) period = "evening";
      else if (h >= 12) period = "afternoon";
      else period = "morning";

      const itemType: "theory" | "practice" | "exam" | "makeup" =
        s.scheduleType === "EXAM" ? "exam" : "theory";
      const row = scheduleMap[dayName];
      if (row?.[period])
        row[period].push({
          id: s.id,
          subject: s.subjectName,
          code: `${s.classCode} - ${s.subjectCode}`,
          sessions: `${s.startTime ?? ""} - ${s.endTime ?? ""}`,
          room: `Phòng: ${s.room}`,
          teacher: `GV: ${s.teacherName}`,
          type: itemType,
        } as ScheduleItem);
    });

    // Sắp xếp các môn trong mỗi ca theo giờ bắt đầu
    Object.keys(scheduleMap).forEach((day) => {
      const row = scheduleMap[day];
      if (row.morning) row.morning.sort((a, b) => a.sessions.localeCompare(b.sessions));
      if (row.afternoon) row.afternoon.sort((a, b) => a.sessions.localeCompare(b.sessions));
      if (row.evening) row.evening.sort((a, b) => a.sessions.localeCompare(b.sessions));
    });

    return scheduleMap;
  };

  // Helper function to apply filter and update schedule
  const applyFilter = (
    schedules: Schedule[],
    view: "all" | "class" | "exam",
  ) => {
    // Filter schedules
    const filtered = schedules.filter((s: Schedule) => {
      if (view === "all") return true;
      if (view === "class") return s.scheduleType !== "EXAM";
      if (view === "exam") return s.scheduleType === "EXAM";
      return true;
    });

    // Convert filtered schedules to DaySchedule format
    return convertSchedulesToDaySchedule(filtered);
  };

  // Load schedules từ backend
  useEffect(() => {
    loadSchedules();
  }, [currentWeek]);

  // Filter schedules based on selectedView and allSchedules
  useEffect(() => {
    if (allSchedules.length === 0 && !isChangingWeek) {
      setWeeklySchedule({});
      return;
    }

    // Smooth fade transition khi đổi tuần hoặc filter
    Animated.timing(fadeAnim, {
      toValue: 0.4,
      duration: 100,
      useNativeDriver: true,
    }).start(() => {
      // Apply filter
      const scheduleMap = applyFilter(allSchedules, selectedView);
      console.log(
        `🔍 Filtered schedules (${selectedView}):`,
        Object.keys(scheduleMap).length,
        "days",
      );
      setWeeklySchedule(scheduleMap);

      // Reset changing week flag
      setIsChangingWeek(false);

      // Fade in animation - mượt hơn
      Animated.timing(fadeAnim, {
        toValue: 1,
        duration: 250,
        useNativeDriver: true,
      }).start();
    });
  }, [selectedView, allSchedules, isChangingWeek]);

  const loadSchedules = async () => {
    try {
      // Chỉ hiển thị loading indicator lớn khi lần đầu load, không hiển thị khi đổi tuần
      if (!isChangingWeek) {
        setLoading(true);
      }
      console.log("📅 Loading weekly schedules...");

      // Tính khoảng ngày của tuần hiện tại (fromDate, toDate - yyyy-MM-dd)
      const startDate = new Date(currentWeek);
      const day = startDate.getDay();
      const diff = startDate.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
      startDate.setDate(diff);
      const endDate = new Date(startDate);
      endDate.setDate(endDate.getDate() + 6);

      const toIsoDate = (d: Date) => {
        const year = d.getFullYear();
        const month = (d.getMonth() + 1).toString().padStart(2, "0");
        const day = d.getDate().toString().padStart(2, "0");
        return `${year}-${month}-${day}`;
      };

      const fromDate = toIsoDate(startDate);
      const toDate = toIsoDate(endDate);

      const params: {
        classId?: string;
        classIds?: string[];
        teacherId?: string;
        scheduleType?: "CLASS" | "EXAM";
        fromDate?: string;
        toDate?: string;
      } = { fromDate, toDate };

      // Teacher mode: dùng teacherId trực tiếp
      if (teacherId) {
        params.teacherId = teacherId;
      } else {
        // /users/me trả về enrolledClassIds (1 SV nhiều môn) hoặc classId
        try {
          const { authService } = await import("@/apis");
          const currentUser = await authService.getCurrentUser();
          if (currentUser?.enrolledClassIds?.length) {
            params.classIds = currentUser.enrolledClassIds;
          } else if (currentUser?.classId) {
            params.classId = currentUser.classId;
          }
        } catch (err) {
          console.warn("⚠️ Không lấy được user, sẽ load toàn bộ lịch:", err);
        }
      }

      if (selectedView === "class") {
        params.scheduleType = "CLASS";
      } else if (selectedView === "exam") {
        params.scheduleType = "EXAM";
      }

      // Nếu không có scheduleType (Tất cả) thì backend trả full, FE chỉ group theo ngày/ca
      const allSchedules = await scheduleService.getSchedules(params);

      console.log("✅ Loaded schedules:", allSchedules.length);
      console.log("📅 Current week:", formatWeekRange());

      // Store all schedules for filtering
      // Filter effect will automatically apply selectedView filter
      setAllSchedules(allSchedules);
    } catch (error: any) {
      console.error("❌ Error loading schedules:", error);
      setWeeklySchedule({});
      setIsChangingWeek(false);
    } finally {
      setLoading(false);
    }
  };

  const getTypeColor = (type: string) => {
    switch (type) {
      case "theory":
        return Colors.success; 
      case "practice":
        return Colors.primary;
      case "exam":
        return Colors.error;
      case "makeup":
        return Colors.warning;
      default:
        return Colors.gray500;
    }
  };

  const getTypeBgColor = (type: string) => {
    switch (type) {
      case "theory":
        return Colors.successLight;
      case "practice":
        return Colors.infoLight;
      case "exam":
        return Colors.errorLight;
      case "makeup":
        return Colors.warningLight;
      default:
        return Colors.gray100;
    }
  };

  const formatWeekRange = () => {
    const startDate = new Date(currentWeek);
    const day = startDate.getDay();
    const diff = startDate.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
    startDate.setDate(diff);
    
    const endDate = new Date(startDate);
    endDate.setDate(endDate.getDate() + 6); // Sunday

    return `${startDate.getDate().toString().padStart(2, "0")}/${(startDate.getMonth() + 1).toString().padStart(2, "0")} - ${endDate.getDate().toString().padStart(2, "0")}/${(endDate.getMonth() + 1).toString().padStart(2, "0")}/${endDate.getFullYear()}`;
  };

  const navigateWeek = (direction: "prev" | "next") => {
    // Smooth fade out trước khi đổi tuần
    setIsChangingWeek(true);
    Animated.timing(fadeAnim, {
      toValue: 0.3,
      duration: 150,
      useNativeDriver: true,
    }).start(() => {
      // Đổi tuần sau khi fade out
      const newDate = new Date(currentWeek);
      newDate.setDate(newDate.getDate() + (direction === "next" ? 7 : -7));
      setCurrentWeek(newDate);
      // loadSchedules sẽ được trigger bởi useEffect, và fade in sẽ được handle bởi filter effect
    });
  };

  const renderScheduleCell = (
    day: string,
    period: "morning" | "afternoon" | "evening",
  ) => {
    const schedules = weeklySchedule[day]?.[period] || [];
    const todayDayName = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"][new Date().getDay()];
    const isToday = day === todayDayName;

    return (
      <View
        key={`${day}-${period}`}
        style={{
          flex: 1,
          minWidth: columnMinWidth,
          minHeight: 120,
          padding: 8,
          borderRightWidth: 1,
          borderRightColor: Colors.border,
          borderBottomWidth: 1,
          borderBottomColor: Colors.border,
          backgroundColor: isToday ? "rgba(59,130,246,0.02)" : (schedules.length > 0 ? Colors.white : Colors.surface),
        }}
      >
        {schedules.length === 0 ? (
          <View style={{ flex: 1, opacity: 0.15, alignItems: "center", justifyContent: "center" }}>
            <View style={{ width: 20, height: 2, backgroundColor: Colors.border, borderRadius: 1 }} />
          </View>
        ) : (
          schedules.map((item, idx) => (
            <TouchableOpacity
              key={item.id}
              activeOpacity={0.8}
              onPress={() => setModalItem({ ...item, day })}
              style={{
                backgroundColor: Colors.white,
                borderLeftWidth: 4,
                borderLeftColor: getTypeColor(item.type),
                borderWidth: 1,
                borderColor: Colors.border,
                padding: 10,
                borderRadius: 12,
                marginBottom: idx < schedules.length - 1 ? 8 : 0,
                ...getWebShadow("sm"),
                ...getWebCursor(),
              }}
            >
              {/* Type badge */}
              {item.type === "exam" && (
                <View style={{ backgroundColor: "#FEE2E2", paddingHorizontal: 6, paddingVertical: 2, borderRadius: 6, alignSelf: "flex-start", marginBottom: 4 }}>
                  <Text style={{ fontSize: 10, fontWeight: "700", color: Colors.error }}>THI</Text>
                </View>
              )}

              {/* Subject name */}
              <Text
                style={{ fontSize: 12, fontWeight: "700", color: Colors.textHeading, marginBottom: 6, lineHeight: 16 }}
                numberOfLines={2}
              >
                {item.subject}
              </Text>

              {/* Teacher */}
              <View style={{ flexDirection: "row", alignItems: "center", gap: 5, marginBottom: 6 }}>
                <View style={{ width: 20, height: 20, borderRadius: 10, backgroundColor: Colors.infoLight, alignItems: "center", justifyContent: "center" }}>
                  <Ionicons name="person" size={11} color={Colors.primary} />
                </View>
                <Text style={{ fontSize: 11, color: Colors.textHeading, fontWeight: "500", flex: 1 }} numberOfLines={1}>
                  {item.teacher.replace("GV: ", "")}
                </Text>
              </View>

              {/* Time + Room */}
              <View style={{ backgroundColor: Colors.surface, borderRadius: 7, padding: 6, gap: 4 }}>
                <View style={{ flexDirection: "row", alignItems: "center", gap: 5 }}>
                  <Ionicons name="time-outline" size={11} color={Colors.primary} />
                  <Text style={{ fontSize: 11, fontWeight: "600", color: Colors.textHeading }}>{item.sessions}</Text>
                </View>
                <View style={{ flexDirection: "row", alignItems: "center", gap: 5 }}>
                  <Ionicons name="business-outline" size={11} color={Colors.success} />
                  <Text style={{ fontSize: 11, fontWeight: "500", color: Colors.textHeading }}>{item.room.replace("Phòng: ", "")}</Text>
                </View>
              </View>
            </TouchableOpacity>
          ))
        )}
      </View>
    );
  };

  return (
    <View style={{ marginBottom: 24, width: "100%" }}>
      {/* Loading Indicator */}
      {loading && (
        <View
          style={{
            backgroundColor: "#FFFFFF",
            borderRadius: 12,
            padding: 24,
            alignItems: "center",
            justifyContent: "center",
            marginBottom: 12,
          }}
        >
          <ActivityIndicator size="small" color={Colors.primary} />
          <Text style={{ marginTop: 8, color: "#6B7280", fontSize: 13 }}>
            Đang tải lịch học...
          </Text>
        </View>
      )}

      {/* Header Controls */}
      <View
        style={{
          backgroundColor: "#FFFFFF",
          borderRadius: 12,
          padding: isMobile ? 12 : 16,
          marginBottom: 12,
          shadowColor: "#000",
          shadowOffset: { width: 0, height: 1 },
          shadowOpacity: 0.05,
          shadowRadius: 2,
          elevation: 1,
        }}
      >
        <Text
          style={{
            fontSize: isMobile ? 16 : 18,
            fontWeight: "bold",
            color: "#111827",
            marginBottom: 12,
          }}
        >
          {teacherId ? "Lịch dạy theo tuần" : "Lịch học, lịch thi theo tuần"}
        </Text>

        <View
          style={{
            flexDirection: isMobile ? "column" : "row",
            alignItems: isMobile ? "stretch" : "center",
            justifyContent: "space-between",
            gap: 12,
          }}
        >
          {/* View Filter Buttons */}
          <View
            style={{
              flexDirection: "row",
              backgroundColor: Colors.gray100,
              borderRadius: 12,
              padding: 4,
            }}
          >
            <TouchableOpacity
              onPress={() => setSelectedView("all")}
              style={{
                paddingHorizontal: 16,
                paddingVertical: 8,
                borderRadius: 8,
                backgroundColor: selectedView === "all" ? Colors.white : "transparent",
                ... (selectedView === "all" ? getWebShadow("sm") : {}),
              }}
            >
              <Text
                style={{
                  fontSize: 13,
                  fontWeight: "700",
                  color: selectedView === "all" ? Colors.primary : Colors.textSecondary,
                }}
              >
                Tất cả
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => setSelectedView("class")}
              style={{
                paddingHorizontal: 16,
                paddingVertical: 8,
                borderRadius: 8,
                backgroundColor: selectedView === "class" ? Colors.white : "transparent",
                ... (selectedView === "class" ? getWebShadow("sm") : {}),
              }}
            >
              <Text
                style={{
                  fontSize: 13,
                  fontWeight: "700",
                  color: selectedView === "class" ? Colors.primary : Colors.textSecondary,
                }}
              >
                Lịch học
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => setSelectedView("exam")}
              style={{
                paddingHorizontal: 16,
                paddingVertical: 8,
                borderRadius: 8,
                backgroundColor: selectedView === "exam" ? Colors.white : "transparent",
                ... (selectedView === "exam" ? getWebShadow("sm") : {}),
              }}
            >
              <Text
                style={{
                  fontSize: 13,
                  fontWeight: "700",
                  color: selectedView === "exam" ? Colors.primary : Colors.textSecondary,
                }}
              >
                Lịch thi
              </Text>
            </TouchableOpacity>
          </View>

          {/* Week Navigation */}
          <View
            style={{
              flexDirection: "row",
              alignItems: "center",
              gap: 12,
              justifyContent: isMobile ? "center" : "flex-end",
            }}
          >
            <TouchableOpacity
              onPress={() => navigateWeek("prev")}
              style={{
                width: 36,
                height: 36,
                borderRadius: 18,
                backgroundColor: Colors.white,
                alignItems: "center",
                justifyContent: "center",
                borderWidth: 1,
                borderColor: Colors.border,
                ...getWebShadow("sm"),
                ...getWebCursor(),
              }}
            >
              <Ionicons name="chevron-back" size={20} color={Colors.textHeading} />
            </TouchableOpacity>

            <View style={{ paddingHorizontal: 12, paddingVertical: 6, backgroundColor: Colors.white, borderRadius: 20, borderWidth: 1, borderColor: Colors.border }}>
              <Text
                style={{
                  fontSize: 14,
                  fontWeight: "700",
                  color: Colors.textHeading,
                  textAlign: "center",
                }}
              >
                {formatWeekRange()}
              </Text>
            </View>

            <TouchableOpacity
              onPress={() => navigateWeek("next")}
              style={{
                width: 36,
                height: 36,
                borderRadius: 18,
                backgroundColor: Colors.white,
                alignItems: "center",
                justifyContent: "center",
                borderWidth: 1,
                borderColor: Colors.border,
                ...getWebShadow("sm"),
                ...getWebCursor(),
              }}
            >
              <Ionicons name="chevron-forward" size={20} color={Colors.textHeading} />
            </TouchableOpacity>
          </View>
        </View>
      </View>

      {/* Mobile Hint */}
      {isMobile && (
        <View
          style={{
            backgroundColor: "#EFF6FF",
            paddingHorizontal: 12,
            paddingVertical: 8,
            borderRadius: 8,
            marginBottom: 12,
            flexDirection: "row",
            alignItems: "center",
            gap: 8,
          }}
        >
          <Text style={{ fontSize: 20 }}>👉</Text>
          <Text style={{ fontSize: 12, color: "#1E40AF", flex: 1 }}>
            Vuốt sang ngang để xem lịch các ngày khác
          </Text>
        </View>
      )}

      {/* Schedule Table */}
      <Animated.View style={{ opacity: fadeAnim }}>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={Platform.OS === "web"}
          style={{
            backgroundColor: Colors.white,
            borderRadius: 20,
            borderWidth: 1,
            borderColor: Colors.border,
            ...getWebShadow("md"),
          }}
          contentContainerStyle={{
            minWidth: "100%",
          }}
        >
          <View style={{ minWidth: "100%" }}>
            {/* Table Header */}
            <View style={{ flexDirection: "row", backgroundColor: "#F9FAFB" }}>
              <View
                style={{
                  width: isMobile ? 80 : 120,
                  padding: headerPadding,
                  borderRightWidth: 1,
                  borderRightColor: "#D1D5DB",
                  borderBottomWidth: 2,
                  borderBottomColor: "#D1D5DB",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                <Text
                  style={{
                    fontSize: headerFontSize,
                    fontWeight: "700",
                    color: "#111827",
                  }}
                >
                  {isMobile ? "Ca" : "Ca học"}
                </Text>
              </View>
              {[
                "Thứ 2",
                "Thứ 3",
                "Thứ 4",
                "Thứ 5",
                "Thứ 6",
                "Thứ 7",
                "Chủ nhật",
              ].map((day, index) => (
                <View
                  key={day}
                  style={{
                    flex: 1,
                    minWidth: columnMinWidth,
                    padding: headerPadding,
                    borderRightWidth: index < 6 ? 1 : 0,
                    borderRightColor: "#D1D5DB",
                    borderBottomWidth: 2,
                    borderBottomColor: "#D1D5DB",
                    justifyContent: "center",
                    alignItems: "center",
                  }}
                >
                  <Text
                    style={{
                      fontSize: dayFontSize,
                      fontWeight: "600",
                      color: "#374151",
                    }}
                  >
                    {isMobile ? day.replace("Thứ ", "T") : day}
                  </Text>
                </View>
              ))}
            </View>

            {/* Cột giống lịch thật: Sáng (tiết 1-6), Chiều (7-12), Tối (13-15). Data map theo giờ vào đúng ca. */}
            <View style={{ flexDirection: "row" }}>
              <View
                style={{
                  width: isMobile ? 80 : 120,
                  padding: headerPadding,
                  borderRightWidth: 1,
                  borderRightColor: "#D1D5DB",
                  borderBottomWidth: 1,
                  borderBottomColor: "#D1D5DB",
                  backgroundColor: "#FFFBEB",
                  justifyContent: "center",
                  alignItems: "center",
                  minHeight: 100,
                }}
              >
                <Text
                  style={{
                    fontSize: periodFontSize,
                    fontWeight: "600",
                    color: "#92400E",
                  }}
                >
                  Sáng
                </Text>
              </View>
              {[
                "monday",
                "tuesday",
                "wednesday",
                "thursday",
                "friday",
                "saturday",
                "sunday",
              ].map((day) => renderScheduleCell(day, "morning"))}
            </View>
            <View style={{ flexDirection: "row" }}>
              <View
                style={{
                  width: isMobile ? 80 : 120,
                  padding: headerPadding,
                  borderRightWidth: 1,
                  borderRightColor: "#D1D5DB",
                  borderBottomWidth: 1,
                  borderBottomColor: "#D1D5DB",
                  backgroundColor: "#FEF3C7",
                  justifyContent: "center",
                  alignItems: "center",
                  minHeight: 100,
                }}
              >
                <Text
                  style={{
                    fontSize: periodFontSize,
                    fontWeight: "600",
                    color: "#92400E",
                  }}
                >
                  Chiều
                </Text>
              </View>
              {[
                "monday",
                "tuesday",
                "wednesday",
                "thursday",
                "friday",
                "saturday",
                "sunday",
              ].map((day) => renderScheduleCell(day, "afternoon"))}
            </View>
            <View style={{ flexDirection: "row" }}>
              <View
                style={{
                  width: isMobile ? 80 : 120,
                  padding: headerPadding,
                  borderRightWidth: 1,
                  borderRightColor: "#D1D5DB",
                  borderBottomWidth: 1,
                  borderBottomColor: "#D1D5DB",
                  backgroundColor: "#DBEAFE",
                  justifyContent: "center",
                  alignItems: "center",
                  minHeight: 100,
                }}
              >
                <Text
                  style={{
                    fontSize: periodFontSize,
                    fontWeight: "600",
                    color: "#1E3A8A",
                  }}
                >
                  Tối
                </Text>
              </View>
              {[
                "monday",
                "tuesday",
                "wednesday",
                "thursday",
                "friday",
                "saturday",
                "sunday",
              ].map((day) => renderScheduleCell(day, "evening"))}
            </View>
          </View>
        </ScrollView>
      </Animated.View>

      {/* Legend */}
      <View
        style={{
          flexDirection: "row",
          flexWrap: "wrap",
          gap: 16,
          marginTop: 12,
          paddingHorizontal: 8,
        }}
      >
        <View style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
          <View
            style={{
              width: 16,
              height: 16,
              backgroundColor: "#D1FAE5",
              borderRadius: 3,
            }}
          />
          <Text style={{ fontSize: 12, color: "#6B7280" }}>
            Lịch học lý thuyết
          </Text>
        </View>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
          <View
            style={{
              width: 16,
              height: 16,
              backgroundColor: "#DBEAFE",
              borderRadius: 3,
            }}
          />
          <Text style={{ fontSize: 12, color: "#6B7280" }}>
            Lịch học thực hành
          </Text>
        </View>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
          <View
            style={{
              width: 16,
              height: 16,
              backgroundColor: "#FEE2E2",
              borderRadius: 3,
            }}
          />
          <Text style={{ fontSize: 12, color: "#6B7280" }}>Lịch thi</Text>
        </View>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
          <View
            style={{
              width: 16,
              height: 16,
              backgroundColor: "#FEF3C7",
              borderRadius: 3,
            }}
          />
          <Text style={{ fontSize: 12, color: "#6B7280" }}>Lịch tạm ngưng</Text>
        </View>
      </View>

      {/* ── Detail Modal ── */}
      <Modal
        visible={!!modalItem}
        transparent
        animationType="fade"
        onRequestClose={() => setModalItem(null)}
      >
        <TouchableOpacity
          style={{ flex: 1, backgroundColor: "rgba(0,0,0,0.5)", justifyContent: "center", alignItems: "center", padding: 16 }}
          activeOpacity={1}
          onPress={() => setModalItem(null)}
        >
          <TouchableOpacity
            activeOpacity={1}
            style={{ width: "100%", maxWidth: 400, backgroundColor: Colors.white, borderRadius: 20, padding: 24, ...getWebShadow("lg") }}
          >
            {modalItem && (
              <>
                {/* Header */}
                <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 20 }}>
                  <View style={{ flex: 1, paddingRight: 12 }}>
                    <View style={{ flexDirection: "row", gap: 8, marginBottom: 8, flexWrap: "wrap" }}>
                      <View style={{
                        paddingHorizontal: 10, paddingVertical: 4, borderRadius: 8,
                        backgroundColor: modalItem.type === "exam" ? "#FEE2E2" : Colors.infoLight,
                      }}>
                        <Text style={{ fontSize: 11, fontWeight: "700", color: modalItem.type === "exam" ? Colors.error : Colors.primary }}>
                          {modalItem.type === "exam" ? "LỊCH THI" : "LỊCH HỌC"}
                        </Text>
                      </View>
                      <View style={{ paddingHorizontal: 10, paddingVertical: 4, borderRadius: 8, backgroundColor: Colors.gray100 }}>
                        <Text style={{ fontSize: 11, fontWeight: "600", color: Colors.textSecondary }}>{modalItem.code}</Text>
                      </View>
                    </View>
                    <Text style={{ fontSize: 18, fontWeight: "700", color: Colors.textHeading, lineHeight: 26 }}>
                      {modalItem.subject}
                    </Text>
                  </View>
                  <TouchableOpacity onPress={() => setModalItem(null)} style={{ padding: 4 }}>
                    <Ionicons name="close" size={24} color={Colors.textSecondary} />
                  </TouchableOpacity>
                </View>

                {/* Divider */}
                <View style={{ height: 1, backgroundColor: Colors.border, marginBottom: 20 }} />

                {/* Details */}
                <View style={{ gap: 16 }}>
                  {[
                    { icon: "person-outline" as const, label: "Giảng viên", value: modalItem.teacher.replace("GV: ", "") },
                    { icon: "business-outline" as const, label: "Phòng học", value: modalItem.room.replace("Phòng: ", "") },
                    { icon: "time-outline" as const, label: "Thời gian", value: modalItem.sessions },
                  ].map((row) => (
                    <View key={row.label} style={{ flexDirection: "row", alignItems: "flex-start", gap: 14 }}>
                      <View style={{ width: 36, height: 36, borderRadius: 10, backgroundColor: Colors.infoLight, alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                        <Ionicons name={row.icon} size={18} color={Colors.primary} />
                      </View>
                      <View style={{ flex: 1 }}>
                        <Text style={{ fontSize: 12, color: Colors.textSecondary, marginBottom: 2 }}>{row.label}</Text>
                        <Text style={{ fontSize: 15, fontWeight: "600", color: Colors.textHeading }}>{row.value}</Text>
                      </View>
                    </View>
                  ))}
                </View>
                {(() => {
                  if (!teacherId || !modalItem) return null;
                  
                  const getMonday = (d: Date): Date => {
                    const copy = new Date(d);
                    const day = copy.getDay();
                    const diff = copy.getDate() - day + (day === 0 ? -6 : 1);
                    copy.setDate(diff);
                    copy.setHours(0, 0, 0, 0);
                    return copy;
                  };

                  const dayOffsets: Record<string, number> = {
                    monday: 0,
                    tuesday: 1,
                    wednesday: 2,
                    thursday: 3,
                    friday: 4,
                    saturday: 5,
                    sunday: 6
                  };

                  const checkIsItemToday = (dayName: string) => {
                    const monday = getMonday(currentWeek);
                    const itemDate = new Date(monday);
                    itemDate.setDate(monday.getDate() + dayOffsets[dayName]);
                    
                    const today = new Date();
                    return itemDate.getFullYear() === today.getFullYear() &&
                           itemDate.getMonth() === today.getMonth() &&
                           itemDate.getDate() === today.getDate();
                  };

                  const isCurrentTimeInRange = (timeStr?: string) => {
                    if (!timeStr) return false;
                    const cleaned = timeStr.replace(/\s+/g, "");
                    const match = cleaned.match(/^(\d{2}:\d{2})[-–](\d{2}:\d{2})$/);
                    if (!match) return false;
                    const [_, start, end] = match;
                    
                    const now = new Date();
                    const currentMins = now.getHours() * 60 + now.getMinutes();
                    
                    const [startH, startM] = start.split(":").map(Number);
                    const [endH, endM] = end.split(":").map(Number);
                    
                    const startMins = startH * 60 + startM;
                    const endMins = endH * 60 + endM;
                    
                    return currentMins >= startMins && currentMins <= endMins;
                  };

                  const isItemToday = checkIsItemToday(modalItem.day);
                  const isTimeInRange = isCurrentTimeInRange(modalItem.sessions);
                  
                  if (!isItemToday || !isTimeInRange) return null;

                  return (
                    <View style={{ marginTop: 20, borderTopWidth: 1, borderTopColor: Colors.border, paddingTop: 16 }}>
                      <Text style={{ fontSize: 13, fontWeight: "700", color: Colors.textSecondary, marginBottom: 10 }}>
                        ⚡ Ca dạy đang diễn ra, chuyển nhanh đến:
                      </Text>
                      <View style={{ flexDirection: "row", gap: 10 }}>
                        <TouchableOpacity
                          onPress={() => {
                            setModalItem(null);
                            router.push("/teacher/generate-qr");
                          }}
                          style={{
                            flex: 1,
                            backgroundColor: Colors.primary,
                            paddingVertical: 10,
                            borderRadius: 10,
                            alignItems: "center",
                            flexDirection: "row",
                            justifyContent: "center",
                            gap: 6,
                            ...getWebCursor(),
                          }}
                        >
                          <Ionicons name="qr-code-outline" size={16} color="#fff" />
                          <Text style={{ color: "#fff", fontWeight: "700", fontSize: 13 }}>Điểm danh QR</Text>
                        </TouchableOpacity>
                        <TouchableOpacity
                          onPress={() => {
                            setModalItem(null);
                            router.push("/teacher/generate-otp");
                          }}
                          style={{
                            flex: 1,
                            backgroundColor: "#10B981",
                            paddingVertical: 10,
                            borderRadius: 10,
                            alignItems: "center",
                            flexDirection: "row",
                            justifyContent: "center",
                            gap: 6,
                            ...getWebCursor(),
                          }}
                        >
                          <Ionicons name="keypad-outline" size={16} color="#fff" />
                          <Text style={{ color: "#fff", fontWeight: "700", fontSize: 13 }}>Điểm danh OTP</Text>
                        </TouchableOpacity>
                      </View>
                    </View>
                  );
                })()}

                {/* Close button */}
                <TouchableOpacity
                  onPress={() => setModalItem(null)}
                  style={{ marginTop: 24, backgroundColor: Colors.primary, paddingVertical: 12, borderRadius: 12, alignItems: "center", ...getWebCursor() }}
                >
                  <Text style={{ color: "#fff", fontWeight: "700", fontSize: 15 }}>Đóng</Text>
                </TouchableOpacity>
              </>
            )}
          </TouchableOpacity>
        </TouchableOpacity>
      </Modal>
    </View>
  );
}
