import React, { useState } from "react";
import { TouchableOpacity, Text, ViewStyle, Platform } from "react-native";
import { Colors } from "@/constants/colors";
import { Spinner } from "./Spinner";
import { LinearGradient } from "expo-linear-gradient";

interface PrimaryButtonProps {
  title: string;
  onPress: () => void;
  loading?: boolean;
  disabled?: boolean;
  variant?: "primary" | "outline" | "ghost";
  style?: ViewStyle;
}

export const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  title,
  onPress,
  loading = false,
  disabled = false,
  variant = "primary",
  style,
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [isPressed, setIsPressed] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const isDisabled = disabled || loading;

  const getButtonStyle = () => {
    if (variant === "outline") {
      return "bg-white border-2";
    }
    if (variant === "ghost") {
      return "bg-transparent";
    }
    return "";
  };

  const getBackgroundColor = () => {
    if (isDisabled) {
      return variant === "outline" ? Colors.white : Colors.gray300;
    }
    if (variant === "outline" || variant === "ghost") {
      return variant === "outline" ? Colors.white : "transparent";
    }
    return "transparent";
  };

  const getGradientColors = () => {
    if (isPressed) {
      return ["#1A3276", "#2F57BF"] as [string, string];
    }
    if (isHovered) {
      return ["#23479F", "#4F8FF9"] as [string, string];
    }
    return ["#1F3D8E", "#3B82F6"] as [string, string];
  };

  const getBorderColor = () => {
    if (variant === "outline") {
      return isDisabled ? Colors.gray300 : Colors.primary;
    }
    return "transparent";
  };

  const getTextColor = () => {
    if (isDisabled && variant !== "outline") {
      return Colors.gray500;
    }
    if (variant === "outline" || variant === "ghost") {
      return isDisabled ? Colors.gray400 : Colors.primary;
    }
    return Colors.white;
  };

  const getFocusStyle = () => {
    if (!isFocused || isDisabled) return {};

    return Platform.OS === "web"
      ? {
          outline: `3px solid ${Colors.focusRing}`,
          outlineOffset: "2px",
        }
      : {};
  };

  const getHoverStyle = () => {
    if (!isHovered || isDisabled) return {};

    return {
      shadowColor: "#000",
      shadowOffset: { width: 0, height: 2 },
      shadowOpacity: 0.15,
      shadowRadius: 6,
      elevation: 4,
    };
  };

  const getPressedStyle = () => {
    if (!isPressed || isDisabled) return {};

    return {
      transform: [{ scale: 0.96 }],
      shadowColor: "#000",
      shadowOffset: { width: 0, height: 1 },
      shadowOpacity: 0.1,
      shadowRadius: 2,
      elevation: 1,
    };
  };

  return (
    <TouchableOpacity
      onPress={isDisabled ? undefined : onPress}
      disabled={isDisabled}
      accessible={true}
      accessibilityRole="button"
      accessibilityLabel={title}
      accessibilityState={{ disabled: isDisabled }}
      activeOpacity={isDisabled ? 1 : 0.7}
      hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }} // Tăng vùng nhấn cho mobile
      style={[
        {
          borderRadius: 8,
          minHeight: 44, // Minimum touch target
          paddingVertical: 12,
          paddingHorizontal: 24,
          alignItems: "center",
          justifyContent: "center",
          backgroundColor: getBackgroundColor(),
          borderColor: getBorderColor(),
          borderWidth: variant === "outline" ? 2 : 0,
        },
        Platform.OS === "web" &&
          ({
            transition: "all 0.2s ease",
            cursor: isDisabled ? "not-allowed" : "pointer",
          } as any),
        getFocusStyle(),
        getHoverStyle(),
        getPressedStyle(),
        style,
      ]}
      onPressIn={() => !isDisabled && setIsPressed(true)}
      onPressOut={() => setIsPressed(false)}
      {...(Platform.OS === "web" &&
        ({
          onMouseEnter: () => setIsHovered(true),
          onMouseLeave: () => setIsHovered(false),
          onFocus: () => setIsFocused(true),
          onBlur: () => setIsFocused(false),
        } as any))}
    >
      {!isDisabled && variant === "primary" ? (
        <LinearGradient
          colors={getGradientColors()}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={{
            position: "absolute",
            top: 0,
            right: 0,
            bottom: 0,
            left: 0,
            borderRadius: 8,
          }}
        />
      ) : null}

      {loading ? (
        <Spinner size={20} color={getTextColor()} />
      ) : (
        <Text
          style={{
            color: getTextColor(),
            fontSize: 16,
            fontWeight: "600",
            letterSpacing: -0.01,
            textAlign: "center",
            width: "100%",
          }}
        >
          {title}
        </Text>
      )}
    </TouchableOpacity>
  );
};

export default PrimaryButton;
